x=np.load("train_x.npy"); y=np.load("train_y.npy"); B=(x>0).astype(float); N=len(y); n=np.bincount(y)
df=B.sum(0); idf=np.log((N+1)/(df+1))+1
F=B*idf; F=F/np.linalg.norm(F,axis=1,keepdims=True); S=np.array([F[y==c].sum(0) for c in range(4)])
C=np.array([B[y==c].sum(0) for c in range(4)])
res={}
for i in range(N):
    Ci=C.copy(); Ci[y[i]]-=B[i]; ni=n.copy(); ni[y[i]]-=1
    Si=S.copy(); Si[y[i]]-=F[i]; Si=Si/np.linalg.norm(Si,axis=1,keepdims=True)
    for a in [1,3]:
        W=np.log((Ci+a)/(Ci+a).sum(1,keepdims=True)); Wc=W-W.mean(0)
        tot=Ci.sum(0)
        comp=np.array([np.log((tot-Ci[c]+a)/(tot-Ci[c]+a).sum()) for c in range(4)]); Wcomp=-comp
        for nm,inp in [("B",B[i]),("x",x[i])]:
            nb=inp@Wc; cnb=inp@Wcomp; ce=(inp*idf)@Si.T
            for k,sc in [("nb",nb),("cnb",cnb),("ce",ce),("ens",nb/ (np.abs(nb).std()+1e-9)*0+nb/10+ce*3),("ens2",nb/10+ce*6)]:
                key=(a,nm,k); res[key]=res.get(key,0)+(sc.argmax()==y[i])
for k,v in sorted(res.items()): print(k, round(v/N,4))
